CREATE DATABASE IF NOT EXISTS portfolio_builder CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE portfolio_builder;

CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('user','admin') NOT NULL DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE templates (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(60) NOT NULL DEFAULT 'Modern', description VARCHAR(255) NOT NULL DEFAULT '', template_file VARCHAR(120) NOT NULL DEFAULT 'modern.php', preview_image VARCHAR(255) DEFAULT NULL, template_html LONGTEXT, template_css LONGTEXT, fields_json LONGTEXT, layout_type ENUM('modern','classic','creative') NOT NULL DEFAULT 'modern', accent_color CHAR(7) NOT NULL DEFAULT '#4f6df5', status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE portfolios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, template_id INT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL DEFAULT 'My Portfolio', full_name VARCHAR(120) NOT NULL, tagline VARCHAR(150) NOT NULL DEFAULT '', about TEXT, email VARCHAR(190) NOT NULL DEFAULT '', phone VARCHAR(50) NOT NULL DEFAULT '', website VARCHAR(255) NOT NULL DEFAULT '', education JSON, skills JSON, projects JSON, experience JSON, certifications JSON, social JSON, custom_data LONGTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE social_links (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, portfolio_id INT UNSIGNED NOT NULL UNIQUE, github VARCHAR(255) DEFAULT '', linkedin VARCHAR(255) DEFAULT '', website VARCHAR(255) DEFAULT '', twitter VARCHAR(255) DEFAULT '', instagram VARCHAR(255) DEFAULT '', FOREIGN KEY (portfolio_id) REFERENCES portfolios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE education (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, portfolio_id INT UNSIGNED NOT NULL, institution VARCHAR(180) NOT NULL, degree VARCHAR(150) NOT NULL, field VARCHAR(150) DEFAULT '', start_date VARCHAR(20) DEFAULT '', end_date VARCHAR(20) DEFAULT '', description TEXT, FOREIGN KEY (portfolio_id) REFERENCES portfolios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE skills (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, portfolio_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, level TINYINT UNSIGNED NOT NULL DEFAULT 75, FOREIGN KEY (portfolio_id) REFERENCES portfolios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, portfolio_id INT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, description TEXT, technologies VARCHAR(255) DEFAULT '', project_url VARCHAR(255) DEFAULT '', github_url VARCHAR(255) DEFAULT '', image VARCHAR(255) DEFAULT '', FOREIGN KEY (portfolio_id) REFERENCES portfolios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE experience (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, portfolio_id INT UNSIGNED NOT NULL, company VARCHAR(180) NOT NULL, job_title VARCHAR(150) NOT NULL, start_date VARCHAR(20) DEFAULT '', end_date VARCHAR(20) DEFAULT '', description TEXT, FOREIGN KEY (portfolio_id) REFERENCES portfolios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE certifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, portfolio_id INT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, organization VARCHAR(180) NOT NULL, issue_date VARCHAR(20) DEFAULT '', credential_url VARCHAR(255) DEFAULT '', FOREIGN KEY (portfolio_id) REFERENCES portfolios(id) ON DELETE CASCADE) ENGINE=InnoDB;

